/* @lc app=leetcode id=3470 lang=kotlin */ class Solution { fun fc(): List<Long> = (1..100).runningFold(1L) { a, i -> minOf(2_000_000_000_000_000L, a * i) } fun sm(a: Long, b: Long): Long = if (a == 0L || b == 0L) 0L else if (a > 2_000_000_000_000_000L / b) 2_000_000_000_000_000L else minOf(2_000_000_000_000_000L, a * b) fun ways(f: List<Long>, rem: List<Int>, nextOdd: Boolean): Long = rem.count { it % 2 == 1 }.let { o -> (rem.size - o).let { e -> if (rem.isEmpty()) 1L else if (if (nextOdd) (o == e || o == e + 1) else (e == o || e == o + 1)) sm(f[o], f[e]) else 0L } } fun permute(n: Int, k: Long): IntArray = fc().let { f -> generateSequence(Triple((1..n).toList(), k, listOf<Int>())) { (rem, kk, out) -> if (rem.isEmpty()) null else rem.filter { out.isEmpty() || (it % 2 == 1) != (out.last() % 2 == 1) }.let { cands -> cands.map { c -> ways(f, rem - c, c % 2 == 0) }.let { cn -> cn.runningFold(0L) { a, b -> a + b }.drop(1).indexOfFirst { it >= kk }.let { idx -> if (idx < 0) null else Triple(rem - cands[idx], kk - cn.take(idx).sum(), out + cands[idx]) } } } }.last().third.let { if (it.size == n) it.toIntArray() else IntArray(0) } } }